/// Plan streams first, then half their remaining room with a 16 GiB floor, unless the cache was explicit.
pub fn budgetOf(comptime F: type, l: kv_pool.Layout, room: u64, o: api.Open, window: u64, host_mode: bool, engine_paged: bool, kept_ppm: u32, slots: ?usize) kv_pool.Budget {
    const rows: u64 = if (comptime @hasDecl(F, "window_rows")) F.window_rows else 0;
    const want = if (host_mode) 0 else cacheWanted(F, o);
    var out: kv_pool.Budget = .{ .room = room, .engine = 0, .lanes = o.lanes, .fixed = o.lanes_fixed, .cache = want, .snaps = slots orelse named(o), .window = window + rows, .engine_paged = engine_paged, .kept_ppm = if (host_mode) 0 else kept_ppm, .slots_only = slots != null, .asked = o.prompt_cache_gib != null, .cache_first = cacheFirst() }; // port note (af9777b49): the fork's TF_PROMPT_CACHE_FIRST rides the upstream budget
    if (out.asked or host_mode or comptime keepsNoPrompts(F)) return out;
    var probe = out;
    probe.cache = std.math.maxInt(u64);
    const all = kv_pool.plan(l, probe) catch return out;
    const left = if (!engine_paged and out.window > 0)
        room -| (@as(u64, all.lanes - 1) *| (l.fixed_bytes +| (l.pages(out.window) + l.runPages()) *| l.pageBytes()))
    else
        all.snaps * l.snap_bytes + all.copied + all.kept;
    out.cache = budget.cacheBytes(null, left, 0);
    return out;
}

/// The room's reserve (TENSORFOLD_MEMORY_RESERVE_GIB) and the least it may be set to, for a refusal's fit; `limited`:
/// TENSORFOLD_CUDA_MEMORY_LIMIT_GB bounds the room, so a smaller reserve may not widen it. // port note (af9777b49): the fork's
pub const Reserve = struct { bytes: u64, least: u64, limited: bool = false };

/// What a plan reads beside the budget: the reserve its refusals price a fit by (null: none named), and the family's
/// smallest kept state (0: no rule), under which a device prompt cache beside a host tier holds nothing.
pub const Facts = struct { reserve: ?Reserve = null, min_state: u64 = 0 };

/// The pool beside the engine's own sequence (in `model`: a window, or on pages its fixed part); null: see `problem`.
